const TAROT_MERCH_TAGS_BY_ID = new Map(TAROT_MERCH_TAGS.map(row => [row.id, row]));

export function tarotTagForId(id) {
  return TAROT_MERCH_TAGS_BY_ID.get(String(id || '').toUpperCase()) || null;
}

/** Filas activas y compra­bles ahora que matchean primary_type/format/deck_family. */
export function tarotTagsMatching({ primaryType, format, deckFamily, language, onlyActive = true } = {}) {
  return TAROT_MERCH_TAGS.filter(row => {
    if (onlyActive && row.status !== 'active') return false;
    if (primaryType && row.primary_type !== primaryType) return false;
    if (format && row.format !== format) return false;
    if (deckFamily && row.deck_family !== deckFamily) return false;
    if (language && row.language !== language) return false;
    return true;
  });
}
